create table if not exists tournaments(id bigint generated by default as identity primary key,name text not null,season text,status text default 'active',created_at timestamptz default now());
create table if not exists teams(id bigint generated by default as identity primary key,name text not null unique,short_name text,logo_url text,created_at timestamptz default now());
create table if not exists players(id bigint generated by default as identity primary key,team_id bigint references teams(id) on delete set null,ign text not null,real_name text,created_at timestamptz default now());
create table if not exists matches(id bigint generated by default as identity primary key,tournament_id bigint references tournaments(id) on delete cascade,group_name text,team_a_id bigint references teams(id),team_b_id bigint references teams(id),score_a integer,score_b integer,status text default 'scheduled',match_date timestamptz,created_at timestamptz default now());
create table if not exists standings(id bigint generated by default as identity primary key,tournament_id bigint references tournaments(id) on delete cascade,group_name text,team_id bigint references teams(id) on delete cascade,wins integer default 0,losses integer default 0,points integer default 0,round_difference integer default 0,unique(tournament_id,group_name,team_id));
create table if not exists news(id bigint generated by default as identity primary key,title text not null,body text,image_url text,published_at timestamptz default now());
